ID='B2787';TAG='332_do';SHARED=['redo'];EXCLUDE_REASON='暂略罕见义、古旧词形和低收益派生。'
D=[['古英语 dōn','做、实施、放置'],['中古英语 don／do','保留动作义，也出现助动词用法'],['英语 do','做；构成疑问、否定或强调']]
DE=[['古英语 dǣd／dēd','行为、所做之事；与 dōn 是同源旁支'],['中古英语 dede','行为；也用于正式文书'],['英语 deed','行为、事迹；契据']]
U=[['古英语 undōn／ondōn','撤销、解开；也可表示毁掉'],['中古英语 undon','承接反向做、解开之义'],['英语 undo','撤销已做之事；解开、毁掉']]
W=[
E('do','动词强读 /duː/，弱读 /də/；唱名英 /dəʊ/、美 /doʊ/','做；实施；疑问、否定或强调的助动词；do〔音乐唱名，另源〕','可以表示“动手做”，也可以只负责把句子搭起来。','日常动词继承古英语 dōn、中古英语 don。does、did、done 属于其屈折变化。音乐唱名 do 则来自意大利语唱名体系，用来替换 ut，与“做”不是同一来源。',[['日常动词：古英语 dōn；音乐唱名：意大利语 do','做；另一路是替换 ut 的唱名'],['中古英语 do；近代音乐用语 do','动词逐渐兼作助动词；唱名独立借入'],['现代英语 do','同形词须按动词或音乐读法区分']],'I do the washing 中，do 真正在表达做事；Do you agree? 中，它不表示另做一件事，只帮助提问。I do agree 把 do 读重，就成了“我确实同意”。英式口语 a do 还可以是一场聚会，来自活动义。','do the work；do your best；do not／don’t；Do you…?；I do agree。一般活动常用 do，制作出东西常用 make，但具体搭配要单独记。','do you make bread? 里的 do 帮助提问，make 才描述制作。唱名 do 的元音与动词 do 不同。',('I’ll do the washing while you cook.','你做饭时，我来洗衣服。'),('Do you need a copy of the report?','你需要一份报告副本吗？'),('I do understand why you’re upset.','我确实明白你为什么难过。'),('The choir sang the scale from do to the higher do.','合唱团从 do 唱音阶，一直唱到高八度的 do。'),sources=['https://www.etymonline.com/word/do','https://www.oxfordlearnersdictionaries.com/definition/english/do1_1']),
E('does','/dʌz/；弱读 /dəz/','do 的第三人称单数现在时','主语变成 he、she、it 或一个单数事物时，用这套形式。','现代拼写可看 do＋-es，但读音不是把 do 原音直接接 /z/。带 -s 的北方形式逐渐取代旧的 doth／doeth，成为标准第三人称形式。',[['古英语 dōn 的第三人称变体','南北方存在不同词尾形式'],['英语北方的 -s 形式，与旧 doth／doeth 并存','-s 形式逐渐进入通行书面语'],['现代英语 does','第三人称单数现在时，读 /dʌz/']],'She does the cooking 中，does 是“做”；Does she cook? 中，它帮忙提问，并承担第三人称标记，所以 cook 后面不再加 -s。这个小词已经把语法变化扛走了。','does the work；doesn’t know；Does it work?；She does like it。','Does she know? 正确；不要再写 Does she knows?。名词 doe“母鹿”的复数也拼 does，但读英 /dəʊz/、美 /doʊz/，是另外的词。',('He does most of the cooking at home.','家里大部分饭菜都是他做的。'),('Does this button save the file?','这个按钮是用来保存文件的吗？'),sources=['https://www.etymonline.com/word/does','https://www.oxfordlearnersdictionaries.com/definition/english/does','https://en.wiktionary.org/wiki/does#English']),
E('did','/dɪd/','do 的过去式','把“做了”或句子的提问、否定放到过去。','继承古英语 dyde，经中古英语 didde、dude 等到 did。更早与古老的词干重叠构形相关；不是现代英语把 do 的 o 按某个通用规则换成 i。',[['古英语 dyde','dōn 的过去式'],['中古英语 didde／dude','继续作为过去时使用'],['英语 did','do 的过去式，也作过去时助动词']],'I did the work 把做事放在过去；Did you finish? 把问题放在过去。后一种句子里 did 已经带了过去时，finish 就用原形。肯定句重读 did 还能强调“确实做过”。','did the work；didn’t see；Did you call?；I did tell you。','过去式是 did，完成时中的过去分词是 done：I did it；I have done it。不要写 I have did it。',('We did all the shopping yesterday.','我们昨天把要买的东西都买齐了。'),('Did you send the final version?','你发出最终版本了吗？'),sources=['https://www.etymonline.com/word/did','https://www.merriam-webster.com/dictionary/did','https://en.wiktionary.org/wiki/did#English']),
E('done','/dʌn/','do 的过去分词；完成的；熟了的','事情已经做到某个结果，或食物已经做熟。','继承古英语过去分词 ġedōn，经中古英语 don／idon／ydon 到 done。它与 did 是同一动词的不同语法形式，不是 did 后来又变成 done。',[['古英语 ġedōn','dōn 的过去分词'],['中古英语 don／idon／ydon','保留完成、做过的分词形式'],['英语 done','过去分词；也作“完成的、熟了的”形容词']],'I’ve done it 强调事情已经做过；I’m done 可以是“我做完了”。The work is done 可能强调工作完成的状态，也可能在上下文中作被动表达。食物 done 是火候到位，不是食物自己“做了事”。','have done；get something done；be done with something；Is it done?。','did 能独立作过去时谓语；done 通常搭配助动词或作形容词。I done it 不是通行标准书面语。',('I’ve done everything on the list.','清单上的事我已经全部做完了。'),('Are you done with the scissors?','你用完剪刀了吗？'),('The cake is done, but it needs time to cool.','蛋糕烤好了，不过还需要时间冷却。'),sources=['https://www.etymonline.com/word/done','https://www.oxfordlearnersdictionaries.com/definition/english/done_1']),
E('doing','/ˈduːɪŋ/','do 的 -ing 形式；所做之事；造成某事的行为','把“做”当成正在展开的活动，或拿出来谈的事情。','do＋-ing，现代拼写保留 o。英语也把这一形式用作动作名词；不要把其中 -ing 一律译成“正在”。',D+[['do ＋ -ing → doing','分词、动名词及行动名词']],'What are you doing? 询问眼下的活动；Learning by doing 是边做边学。This was her doing 则把结果归到她头上：这件事是她干的或促成的，语气未必都是责怪。','be doing；learn by doing；be someone’s doing；in doing so。','doing 是动作形式；doings 常是一个人或群体的一连串活动、行迹，语感更像“都干了些什么”。',('What are you doing with those empty boxes?','你正拿那些空盒子做什么？'),('The surprise party was entirely her doing.','这场惊喜聚会完全是她一手安排的。'),sources=['https://www.etymonline.com/word/doing','https://www.oxfordlearnersdictionaries.com/definition/english/doing']),
E('doings','/ˈduːɪŋz/','活动；行迹；所作所为〔复数〕','把某人一阵子里干的事情合在一起看。','动作名词 doing 的复数，用来概括活动、事迹或行踪。是英语内部的名词用法，不是动词第三人称形式。',D+[['doing：所做之事 → doings','复数概括一连串活动或行迹']],'doings 常有一点打听、观察或叙事的味道：这个人最近都在忙些什么？它能指可疑活动，也能写村子里普通的社交生活，本身不等于犯罪。','the doings of a group；secret doings；daily doings。通常作复数名词。','activities 是更中性的通用词；doings 常把读者的注意力带到人物及其所作所为上。',('Her letters describe the daily doings of the village.','她的信描写了村里日常发生的各种事情。'),('The detective began asking about the club’s secret doings.','侦探开始打听那个俱乐部暗中进行的活动。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/doings','https://en.wiktionary.org/wiki/doings#English']),
E('deed','/diːd/','行为；事迹；契据','既可以是实际做出的一件事，也可以是把法律事项正式记下的文书。','继承古英语 dǣd／dēd，经中古英语 dede 到 deed。与 do 在更早的日耳曼、印欧层面同源，但不是现代 do 加一个后缀变来的。',DE,'good deeds 是真正做出来的好事，和只说好听的话相对。契据义从正式行为、交易记录这一方向发展；例如 property deed 是与产权有关的正式文书。词义有关联，不能把任何纸条都叫 deed。','a good deed；heroic deeds；in word and deed；a property deed；title deeds。','action 很通用；deed 常突出值得评价或记述的行为。法律文书义也不等于普通收据 receipt。',('One small deed of kindness changed his whole day.','一个小小的善举让他一整天的心情都变了。'),('She found the old property deeds in a locked drawer.','她在上锁的抽屉里找到了那些旧房产契据。'),sources=['https://www.etymonline.com/word/deed','https://www.oxfordlearnersdictionaries.com/definition/english/deed']),
E('misdeed','/ˌmɪsˈdiːd/','不当行为；坏事；过错','确实做下的一件不好的事。','现代可看 mis-“错误、不当”＋deed“行为”；这个组合在古英语 misdǣd／misdēd 中已经存在，不能说是近代英语临时拼出的。',[['古英语 misdǣd／misdēd','mis- 不当＋行为名词'],['中古英语 misdede','坏事、过错'],['英语 misdeed','受到责备的不当行为']],'misdeed 通常把过错当作一件可指出来的事情，常用复数概括某人的种种劣行。它可以很严重，也可以是在文学或略带戏谑的语境中说一件坏事，并不自动构成具体法律罪名。','past misdeeds；financial misdeeds；admit a misdeed；expose someone’s misdeeds。','mistake 可以是无意的失误；misdeed 更强调行为在道德或规则上不对。',('The memoir does not hide the author’s youthful misdeeds.','这部回忆录没有掩饰作者年轻时做过的坏事。'),('He admitted his misdeed and returned the stolen money.','他承认了自己的过错，并归还了偷来的钱。'),sources=['https://www.etymonline.com/word/misdeed','https://www.merriam-webster.com/dictionary/misdeed']),
E('indeed','/ɪnˈdiːd/','确实；的确；甚至；真的吗〔回应语气〕','把一句话再按实一点：情况确实如此，甚至还不止如此。','由中古英语短语 in dede“事实上、确实”合写，里面的 deed 是实际行为、事实这一支，不是契据。',[['古英语 dǣd → 中古英语 dede','实际做出的事、行为'],['中古英语 in dede','在事实中；确实'],['英语 indeed','短语合为一词，用于确认和加强']],'He was indeed right 是确认他确实对。very useful indeed 则加强“很有用”。单独说 Indeed? 时，语调可以表示惊讶、追问，也可能带怀疑，不能机械地全译成“确实”。','indeed true；very helpful indeed；Yes, indeed；Indeed?。书面语中也可引出进一步说明。','in fact 常补充事实或纠正印象；indeed 常确认、加强前面的说法，两者有重叠但语气不总一样。',('The task was difficult indeed, but we finished it.','这项任务确实很难，但我们完成了。'),('The museum is popular; indeed, tickets often sell out by noon.','这家博物馆很受欢迎；事实上，门票常常中午前就卖完了。'),sources=['https://www.etymonline.com/word/indeed','https://www.oxfordlearnersdictionaries.com/definition/english/indeed']),
E('undo','/ʌnˈduː/','撤销；解开；使前功尽弃','沿着已经做过的动作往回走。','现代可拆 un-“反向、撤回”＋do；古英语 undōn／ondōn 已有撤销、解开的意思，是继承词，不是计算机时代才造出的。',U,'系上一个结，再 undo，就是解开；在编辑器里 undo，就是撤回刚才的操作。它也可以比喻毁掉成果：一个错误把几个月的努力抵消了。','undo a knot；undo a change；undo the damage；undo someone’s work。变化为 undo—undid—undone。','not do 是不去做；undo 是把已经做出的结果倒回去。有些结果无法完全 undo。',('Press this button to undo the last change.','按这个按钮可以撤销最后一次修改。'),('She carefully undid the knot in the ribbon.','她小心地解开了丝带上的结。'),sources=['https://www.etymonline.com/word/undo','https://en.wiktionary.org/wiki/undo#English']),
E('undone','/ʌnˈdʌn/','没做完的；解开的；被毁掉的；undo 的过去分词','先看是“还没做”，还是“做好的东西又被解开了”。','两条构形在这里同形：否定 un-＋done 表示未完成；undo 的过去分词则表示撤销、松开或毁掉。后一条接旧英语的解开动词，不要把两种 un- 合成一个意思。',[['两条材料：done 完成；undo 撤销、解开','未完成与撤销后的结果并非同一结构'],['un- ＋ done；undo 的过去分词 undone','否定义与反向动作的分词并存'],['英语 undone','未完成；松开；毁掉等结果状态']],'leave the work undone 是工作没完成；the lace came undone 是鞋带原本系着，后来松开了。文学里 a person undone 还可以说一个人彻底垮掉，像支撑他的东西被拆散。','leave something undone；come undone；be undone by a mistake。','unfinished 主要说没有完成；undone 除此之外还可以表示松开、被撤销，必须看上下文。',('Several important tasks were left undone.','几项重要任务还没有完成。'),('My shoelace came undone as I was running.','我跑步时鞋带松开了。'),sources=['https://www.etymonline.com/word/undone','https://en.wiktionary.org/wiki/undone#English']),
E('doable','/ˈduːəbəl/','做得到的；可行的','这件事有办法完成，不至于超出手头条件。','do＋-able“可以……的”，中古英语已有 doable。日耳曼本源动词接上来自法语、拉丁语体系的后缀，是英语常见的混合构词。',D[:1]+[['中古英语 doable','do 接 -able，表示能够做成'],['英语 doable','现实条件下可以完成的']],'doable 往往是在估量时间、精力和资源：很难，但不是没办法。它不保证一定成功，只说方案还落在可完成的范围内。','a doable task；a doable plan；difficult but doable；make something doable。','possible 范围很宽，理论上可能也算；doable 常更贴近实际执行。',('The deadline is tight, but the project is doable.','期限很紧，但这个项目还是做得完的。'),('Breaking the work into small steps made it feel doable.','把工作拆成小步骤后，感觉就能做下去了。'),sources=['https://en.wiktionary.org/wiki/doable#English','https://www.oxfordlearnersdictionaries.com/definition/english/doable']),
E('overdo','英 /ˌəʊvəˈduː/；美 /ˌoʊvərˈduː/','做过头；过分；使过火','本来适量就好，却越过了合适的程度。','现代是 over-“过度”＋do；古英语 oferdōn、中古英语 overdon 已有这一组合，不是近代才造出的。',[['古英语 oferdōn','ofer- 超过＋dōn 做'],['中古英语 overdon','做过分、超过限度'],['英语 overdo','用力、装饰、表达或烹饪等过度']],'overdo the decoration 是装饰太多；overdo the praise 是夸得让人不舒服。关键不是动作坏，而是程度越界了。单说 Don’t overdo it 就是别弄得太过。','overdo it；overdo the makeup；overdo the special effects；overdo—overdid—overdone。','redo 是重做；overdo 是做过头。overwork 更专指工作过度，overdo 可用于很多动作。',('The film overdoes the special effects.','这部电影的特效用得太过了。'),('A little decoration is enough; don’t overdo it.','稍微装饰一下就够了，别弄得太满。'),sources=['https://en.wiktionary.org/wiki/overdo#English','https://www.oxfordlearnersdictionaries.com/definition/english/overdo']),
E('outdo','/ˌaʊtˈduː/','超过；胜过','做同一件事时，比对方更出色或做得更多。','out- 在这里表示超越，加 do；这是英语内部的派生，不是“到外面做”。',D+[['out- 超越 ＋ do → outdo','在表现或程度上超过']],'想象两个人都在布置展台，一方不断加巧思，希望 outdo the other。outdo yourself 是比自己以前还出色，常用来称赞一次格外成功的表现。','outdo a rival；outdo each other；outdo yourself；outdo—outdid—outdone。','overdo 强调超过合适尺度，可能不好；outdo 强调超过比较对象，不必带负面评价。',('The two teams tried to outdo each other with creative designs.','两支队伍都想用有创意的设计超过对方。'),('You’ve outdone yourself with this meal.','你这顿饭做得比以往还出色。'),sources=['https://www.etymonline.com/word/outdo','https://www.oxfordlearnersdictionaries.com/definition/english/outdo']),
E('doer','英 /ˈduːə/；美 /ˈduːər/','实干者；做某事的人','把想法拿去落实的人。','现代可看 do＋-er；古英语 dōere、中古英语 doer 已有行动者、工作者之义，是长期传下来的名词。',[['古英语 dōere','dōn 对应的行动者名词'],['中古英语 doer／doere','做事的人'],['英语 doer','行动者；尤其指实干者']],'a doer 常带肯定：这个人不只开会讨论，也会把东西做出来。the doer of a deed 更书面，只是指出行为实施者，未必赞扬。','a practical doer；a thinker and a doer；the doer of a good deed。','a worker 强调劳动或职业身份；a doer 强调有行动、能落实。',('We need a doer who can turn the plan into a working service.','我们需要一个能把计划变成实际服务的实干者。'),('The doer of the kind deed left without giving a name.','那位做了善事的人没有留下姓名就走了。'),sources=['https://en.wiktionary.org/wiki/doer#English','https://www.oxfordlearnersdictionaries.com/definition/english/doer']),
E('wrongdoing','英 /ˈrɒŋduːɪŋ/；美 /ˈrɔːŋduːɪŋ/','不当行为；违法或不道德的行为','做的事越过了规则或道德界线。','wrong＋doing；中古英语已有 wrong doyng 一类组合，后来合写为 wrongdoing。doing 指行动，wrong 判断它不正当。',[['中古英语 wrong；doyng','不当；所做的事'],['中古英语 wrong doyng 等','不正当的行动组合'],['英语 wrongdoing','合写后概括不法或失当行为']],'它常见于调查报道：是否有人隐瞒信息、滥用资源或违反规定。它比普通“做错一道题”的错误更有行为责任意味，但具体是否违法要看事情，词本身不是某个确定罪名。','evidence of wrongdoing；deny wrongdoing；allegations of wrongdoing；report wrongdoing。','error 可以只是技术或判断失误；wrongdoing 通常暗示行为不正当。misdeed 更容易指一件具体坏事。',('The review found no evidence of wrongdoing.','审查没有发现不当行为的证据。'),('The company introduced a channel for reporting wrongdoing.','公司设立了举报不当行为的渠道。'),sources=['https://en.wiktionary.org/wiki/wrongdoing#English','https://www.oxfordlearnersdictionaries.com/definition/english/wrongdoing']),
E('hairdo','英 /ˈheəduː/；美 /ˈherduː/','发型〔口语〕','头发经过一番打理后呈现出来的样子。','hair＋do；do 在这里接“整理、打理”的动作义，整个组合名词指打理出的发型。',[['英语 hair；do','头发；整理、打理'],['英语 hairdo','合成名词：做出来的发型']],'说 a new hairdo，重点是头发被弄成了新样子，可能是卷发、盘发或别的造型。语气比 hairstyle 随意，有时还带一点对夸张发型的调侃。','a new hairdo；an elaborate hairdo；change your hairdo。复数 hairdos。','haircut 侧重剪发及剪后的式样；hairdo 可以完全不剪，只是重新梳理或盘起来。',('She arrived with a bright scarf and a new hairdo.','她戴着鲜艳的围巾，换了个新发型来到这里。'),('The wind ruined my carefully arranged hairdo.','风把我精心弄好的发型吹乱了。'),sources=['https://www.etymonline.com/word/hairdo','https://www.oxfordlearnersdictionaries.com/definition/english/hairdo']),
E('updo','/ˈʌpduː/','盘起或向上收拢的发型','把头发从颈部收上去，固定成一个造型。','可按 up＋do 理解；Merriam-Webster 将来源分析为 upswept hairdo 的压缩，即“向上梳拢的发型”。这里的 do 接 hairdo，不是音乐唱名。',[['英语 upswept；hairdo','向上梳拢的；发型'],['压缩组合 updo','把向上的方向和发型结合起来'],['现代英语 updo','盘发、向上固定的造型']],'它可以是整齐的发髻，也可以是松散地盘在后面的造型；核心在头发被收上去，而不是某一种固定扎法。','a loose updo；an elegant updo；wear your hair in an updo。复数 updos。','hairdo 是发型总称；updo 是头发收拢向上的一类。',('She chose a simple updo for the wedding.','她为婚礼选了一个简洁的盘发造型。'),('A few pins held the loose updo in place.','几枚发夹固定住了那个松松的盘发。'),sources=['https://www.merriam-webster.com/dictionary/updo','https://en.wiktionary.org/wiki/updo#English'])]
ROOT=dict(meaning='做、实施；辅助表达疑问、否定和强调',core='一方面实际做事，一方面在句子里承担语法工作。',image='把事情做成；往回做是 undo，重新做是 redo，做过头是 overdo，比别人更好是 outdo。',intro='do 经古英语 dōn 传下，是英语最基本的动作词之一。does、did、done、doing 是同一动词的变化。deed 则继承古英语自己的名词形式，与 do 是古老的同源旁支，不能当作现代 do 临时变出的名词。',forms='do—did—done；第三人称 does；-ing 形式 doing。词缀派生常保留这些不规则变化，例如 undo—undid—undone。',branches=[['动作与语法形式','do；does；did；done；doing；doings'],['反向、重来与程度','undo；undone；redo；overdo；outdo；doable；doer'],['实际行为与评价','deed；misdeed；wrongdoing；indeed'],['把头发打理成型','hairdo；updo']],contrasts='do /duː/ 和唱名 do /dəʊ, doʊ/ 同形而不同源。undone 又有“尚未完成”和“已被解开”两条结构。do 与 make 的选择不能只靠中文“做”，需要记具体搭配。',practice='比较 do、undo、redo、overdo、outdo：分别是做、撤回、重来、过头和超过别人。再用 I did it 与 I have done it 练熟过去式和过去分词。',sources=['https://www.etymonline.com/word/do','https://www.etymonline.com/word/deed','https://www.etymonline.com/word/undone'])
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']==ID);c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']==ID);keep={w['word']for w in W}|set(SHARED);excluded={w:EXCLUDE_REASON for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
ROOT['id']=ID;ROOT['words']=list(dict.fromkeys([w for w in r['family']if w in keep]+[w for w in SHARED if w not in r['family']]));ROOT['exclude']=excluded
assert all(w['word']in m['owned_words']for w in W)
assert not(set(c['family'])|set(c.get('unmatched',[])))-set(ROOT['words'])-set(excluded)
assert {w['word']for w in W}<=set(ROOT['words'])
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history'])
for k,d in [('roots',[ROOT]),('words',W)]: (OUT/f'{k}_batch200_spec_{TAG}.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print(ID,len(W),'new,',len(SHARED),'shared')
